# Meta Box "Detalles del Libro" — Código Completo

## Estructura del archivo `book-details.php`

```php
<?php
/**
 * Plugin Name: Detalles del Libro - Meta Box
 * Description: Añade un metabox con campos de editorial, año e ISBN al editor de entradas.
 * Version: 1.0.0
 * Author: Tu Nombre
 */

// ─── Evitar acceso directo ────────────────────────────────────────────────
if (! defined('ABSPATH')) {
    exit;
}

// ═══════════════════════════════════════════════════════════════════════════
//  1. REGISTRO DEL METABOX
// ═══════════════════════════════════════════════════════════════════════════

add_action('add_meta_boxes', 'bd_register_meta_box');

function bd_register_meta_box(): void
{
    add_meta_box(
        'bd_book_details',            // ID único del metabox
        __('📖 Detalles del Libro', 'bd-textdomain'), // Título visible
        'bd_render_meta_box',         // Callback de renderizado
        ['post'],                     // Post type (añadir 'page' si se necesita)
        'side',                       // Contexto: normal / side / advanced
        'default'                     // Prioridad: high / low / default
    );
}


// ═══════════════════════════════════════════════════════════════════════════
//  2. RENDERIZADO DEL METABOX
// ═══════════════════════════════════════════════════════════════════════════

function bd_render_meta_box(WP_Post $post): void
{
    // Campo nonce para validación de seguridad
    wp_nonce_field('bd_save_book_details', 'bd_nonce');

    // Recuperar valores existentes (si los hay)
    $editorial = get_post_meta($post->ID, '_bd_editorial', true);
    $año       = get_post_meta($post->ID, '_bd_año', true);
    $isbn      = get_post_meta($post->ID, '_bd_isbn', true);

    // Definir campos con sus etiquetas
    $fields = [
        'editorial' => [
            'label'   => __('Editorial', 'bd-textdomain'),
            'type'    => 'text',
            'value'   => esc_attr($editorial),
            'placeholder' => 'Ej: Penguin Random House',
        ],
        'año' => [
            'label'   => __('Año de publicación', 'bd-textdomain'),
            'type'    => 'number',
            'value'   => esc_attr($año),
            'placeholder' => 'Ej: 2024',
            'min'     => '1000',
            'max'     => (string) date('Y'),
        ],
        'isbn' => [
            'label'   => __('ISBN', 'bd-textdomain'),
            'type'    => 'text',
            'value'   => esc_attr($isbn),
            'placeholder' => 'Ej: 978-3-16-148410-0',
        ],
    ];

    // ── HTML del metabox ───────────────────────────────────────────────
?>
<div class="bd-metabox-wrapper">

    <?php foreach ($fields as $key => $field): ?>
        <div class="bd-field">
            <label for="bd_<?php echo esc_attr($key); ?>">
                <?php echo esc_html($field['label']); ?>
            </label>

            <input
                type="<?php echo esc_attr($field['type']); ?>"
                id="bd_<?php echo esc_attr($key); ?>"
                name="bd_<?php echo esc_attr($key); ?>"
                value="<?php echo $field['value']; ?>"
                placeholder="<?php echo esc_attr($field['placeholder'] ?? ''); ?>"
                <?php
                    // Atributos extra según tipo
                    if (! empty($field['min'])) {
                        echo ' min="' . esc_attr($field['min']) . '"';
                    }
                    if (! empty($field['max'])) {
                        echo ' max="' . esc_attr($field['max']) . '"';
                    }
                ?>
                class="widefat"
            />
        </div>
    <?php endforeach; ?>

</div>

<style>
    .bd-metabox-wrapper {
        display: flex;
        flex-direction: column;
        gap: 12px;
    }
    .bd-field label {
        display: block;
        font-weight: 600;
        margin-bottom: 4px;
        font-size: 13px;
    }
    .bd-field input {
        width: 100%;
        box-sizing: border-box;
    }
</style>

<?php
}


// ═══════════════════════════════════════════════════════════════════════════
//  3. GUARDADO CON SANITIZACIÓN
// ═══════════════════════════════════════════════════════════════════════════

add_action('save_post', 'bd_save_book_details', 10, 3);

function bd_save_book_details(int $post_id, WP_Post $post, bool $update): void
{
    // ── 3.1. Validaciones previas ────────────────────────────────────────

    // Verificar nonce
    if (! isset($_POST['bd_nonce']) || ! wp_verify_nonce($_POST['bd_nonce'], 'bd_save_book_details')) {
        return;
    }

    // Verificar permisos del usuario
    if (! current_user_can('edit_post', $post_id)) {
        return;
    }

    // Evitar guardado en autosave (ya se maneja solo, pero por seguridad)
    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
        return;
    }

    // Si el post type no es 'post'
    if ('post' !== $post->post_type) {
        return;
    }

    // ── 3.2. Sanitización de datos ───────────────────────────────────────

    $sanitized = [
        '_bd_editorial' => sanitize_text_field(
            isset($_POST['bd_editorial']) ? $_POST['bd_editorial'] : ''
        ),
        '_bd_año'       => absint(
            isset($_POST['bd_año']) ? $_POST['bd_año'] : 0
        ),
        '_bd_isbn'      => sanitize_text_field(
            isset($_POST['bd_isbn']) ? $_POST['bd_isbn'] : ''
        ),
    ];

    // ── 3.3. Guardar en la base de datos ─────────────────────────────────

    foreach ($sanitized as $meta_key => $value) {
        update_post_meta($post_id, $meta_key, $value);
    }
}


// ═══════════════════════════════════════════════════════════════════════════
//  4. RENDERIZADO EN EL FRONTEND (HOOK DE TEMPLATE)
// ═══════════════════════════════════════════════════════════════════════════

add_action('the_content', 'bd_render_book_details_in_content');

function bd_render_book_details_in_content(string $content): string
{
    // Solo mostrar en posts individuales
    if (! is_singular('post')) {
        return $content;
    }

    global $post;
    $editorial = get_post_meta($post->ID, '_bd_editorial', true);
    $año       = get_post_meta($post->ID, '_bd_año', true);
    $isbn      = get_post_meta($post->ID, '_bd_isbn', true);

    // Si no hay datos, retornar contenido sin cambios
    if (empty($editorial) && empty($año) && empty($isbn)) {
        return $content;
    }

    // Construir bloque HTML con datos sanitizados para salida
    $details_html = '<div class="bd-book-details">';
    $details_html .= '<h3>' . esc_html__('Detalles del Libro', 'bd-textdomain') . '</h3>';
    $details_html .= '<dl>';

    if (! empty($editorial)) {
        $details_html .= '<dt>' . esc_html__('Editorial:', 'bd-textdomain') . '</dt>';
        $details_html .= '<dd>' . esc_html($editorial) . '</dd>';
    }

    if (! empty($año)) {
        $details_html .= '<dt>' . esc_html__('Año:', 'bd-textdomain') . '</dt>';
        $details_html .= '<dd>' . esc_html((int) $año) . '</dd>';
    }

    if (! empty($isbn)) {
        $details_html .= '<dt>' . esc_html__('ISBN:', 'bd-textdomain') . '</dt>';
        $details_html .= '<dd>' . esc_html($isbn) . '</dd>';
    }

    $details_html .= '</dl></div>';

    // Insertar después del contenido
    return $content . $details_html;
}


// ═══════════════════════════════════════════════════════════════════════════
//  5. ESTILOS CSS EN ADMIN
// ═══════════════════════════════════════════════════════════════════════════

add_action('admin_head-post.php', 'bd_admin_styles');
add_action('admin_head-post-new.php', 'bd_admin_styles');

function bd_admin_styles(): void
{
?>
<style>
    #bd_book_details .inside {
        margin: 0;
        padding: 12px;
    }
    .bd-book-details {
        background: #f9f9f9;
        border: 1px solid #ddd;
        border-radius: 4px;
        padding: 16px;
        margin: 20px 0;
    }
    .bd-book-details h3 {
        margin-top: 0;
        margin-bottom: 8px;
    }
    .bd-book-details dl {
        display: grid;
        grid-template-columns: max-content auto;
        gap: 4px 12px;
    }
    .bd-book-details dt {
        font-weight: 600;
    }
</style>
<?php
}
```

